M_PER_DEG = 111_320.0


def _distance_m(a, b):
    dlat = (b.y - a.y) * M_PER_DEG
    dlng = (b.x - a.x) * M_PER_DEG * math.cos(math.radians((a.y + b.y) / 2))
    return math.hypot(dlat, dlng)


def split_outlier_flag(apps, schema_editor):
    """is_outlier used to mean "far from the cluster or outside the ward".

    Set is_outside_ward_boundary from the ward, and keep is_outlier only for
    suggestions far from the centroid of the centre's suggestions, as
    stations.verification now computes them. Upvotes never cluster, so they
    are never far.
    """
    Verification = apps.get_model("stations", "PollingCenterVerification")
    rows = (
        Verification.objects.filter(pin_location__isnull=False)
        .select_related("polling_center__ward")
        .order_by("polling_center_id")
    )
    by_centre = {}
    for row in rows:
        by_centre.setdefault(row.polling_center_id, []).append(row)

    for group in by_centre.values():
        ward = group[0].polling_center.ward
        boundary = ward.boundary if ward else None
        suggestions = [r for r in group if not r.is_upvote]
        centroid = None
        if suggestions:
            pins = [r.pin_location for r in suggestions]
            centroid = type(pins[0])(
                median(p.x for p in pins), median(p.y for p in pins)
            )
        for row in group:
            outside = boundary is not None and not boundary.contains(row.pin_location)
            far = (
                not row.is_upvote
                and _distance_m(row.pin_location, centroid)
                > settings.CONSENSUS_RADIUS_M
            )
            if (row.is_outlier, row.is_outside_ward_boundary) != (far, outside):
                row.is_outlier = far
                row.is_outside_ward_boundary = outside
                row.save(update_fields=["is_outlier", "is_outside_ward_boundary"])


